def p(file, line):
    with open(file, "r") as f:
        lines = f.readlines()
        if line <= len(lines):
            print(f"{file}:{line} - {lines[line-1].strip()}")
def repl(f, o, n):
    with open(f, "r") as x: c = x.read()
    c = c.replace(o, n)
    with open(f, "w") as x: x.write(c)

